//! Interactive prompts.

use console::{style, Key, Style, Term};
use dialoguer::theme::ColorfulTheme;
use dialoguer::{Confirm, Input, MultiSelect, Select};

use crate::error::{BivvyError, Result};

use super::{Prompt, PromptOption, PromptResult, PromptType};

/// ASCII EOT (End of Transmission) — the byte sent by Ctrl+D in raw mode.
const CTRL_D: char = '\x04';

/// Convert dialoguer errors to BivvyError.
fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
    BivvyError::Io(e.into())
}

/// IO error returned when the user signals EOF (Ctrl+D).
fn eof_error() -> BivvyError {
    BivvyError::Io(std::io::Error::new(
        std::io::ErrorKind::UnexpectedEof,
        "input closed (Ctrl+D)",
    ))
}

/// Read a key from the terminal, catching panics from the console crate.
///
/// Console 0.16.x may panic internally on EOF/Ctrl+D depending on platform
/// and terminal state. This wrapper converts such panics to IO errors.
fn read_key_safe(term: &Term) -> std::result::Result<Key, BivvyError> {
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| term.read_key())) {
        Ok(Ok(key)) => Ok(key),
        Ok(Err(e)) => Err(BivvyError::Io(e)),
        Err(_) => Err(eof_error()),
    }
}

/// Run a dialoguer interaction, catching internal panics.
///
/// Dialoguer 0.12.x may panic on EOF/Ctrl+D due to unwrap calls in its
/// rendering or input handling. This wrapper converts such panics to errors.
fn catch_interact<T>(f: impl FnOnce() -> std::result::Result<T, dialoguer::Error>) -> Result<T> {
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)) {
        Ok(Ok(val)) => Ok(val),
        Ok(Err(e)) => Err(map_dialoguer_err(e)),
        Err(_) => Err(eof_error()),
    }
}

